// DAILY SUBLIME EMAIL SYSTEM - 3 TEMPLATES
// 1. Outreach Email (dual CTA)
// 2. Partnership Response
// 3. Trial Response

function escapeHtml(text) {
  if (!text) return '';
  return String(text)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#039;');
}

function formatLineBreaks(text) {
  if (!text) return '';
  return escapeHtml(text).replace(/\n/g, '</p><p style="margin:0;padding-top:16px;">');
}

var inputData = $input.item.json;
var emailType = inputData.Email_Type || 'outreach';
var name = inputData.Influencer_Name || 'Friend';
var profilePic = inputData.Profile_Pic_Url || '';
var personalBody = inputData.Personal_Body || '';
var recipientEmail = inputData.Recipient_Email || '';
var creatorName = inputData.Creator_Name || '[Creator Name]';

var escapedName = escapeHtml(name);
var formattedBody = '<p style="margin:0;">' + formatLineBreaks(personalBody) + '</p>';

var html = '';
var subject = '';

// OUTREACH EMAIL
if (emailType === 'outreach') {
  subject = escapedName + ', a thought for you ✦';
  html = generateOutreachEmail(escapedName, profilePic, formattedBody);
}
// PARTNERSHIP RESPONSE
else if (emailType === 'partnership') {
  subject = "Let's start the Daily Sublime partnership";
  html = generatePartnershipEmail(creatorName);
}
// TRIAL RESPONSE 
else if (emailType === 'trial') {
  subject = "I'd like to try Daily Sublime first";
  html = generateTrialEmail(creatorName);
}

